;==========================================================================
;  Grammar tables
;==========================================================================
;
;  The LL(1) tables that LL1.ASM interprets, generated by tools/llgen.ts
;  from grammar/grammar.json (deno task grammar); tests/llgen_test.ts
;  checks that this file is current. Edit the grammar, not this file.
;
;  Grammar symbols are bytes: $00..$3F a token kind, $40..$7F nonterminal
;  (row) n-$40, $80..$FE action n-$80 (LL1.ASM).
;
;  GR_ROWX   two bytes per nonterminal: the offset of its row from GR_ROWS,
;            then the diagnostic raised when no production of the row is
;            predicted by the next token.
;  GR_ROWS   the rows. A row is a list of alternatives: a production byte,
;            then the token kinds that predict it. Bit 7 marks the last
;            token of each alternative and, on the production byte, the
;            row's last alternative.
;  GR_ALTX   one byte per production below GR_SPLIT: the offset of its body
;            from GR_ALTS, then one entry more that ends the last body. The
;            length of a body is the next entry minus its own.
;  GR_ALTXH  the same for productions GR_SPLIT and up, renumbered from zero,
;            with bodies from GR_ALTHI. Splitting the bodies in two keeps
;            every offset within a byte.
;  GR_ALTS   production bodies, each stored right to left so that the engine
;            pushes it in one copy and its leftmost symbol ends on top.
;            Productions with the same body share it and its number.
;  GR_ACTX   one word per action: the routine LL1.ASM calls, with the
;            action ordinal in A.
;
;  Names. GR_ROWn is row n (nonterminal $40+n) and GR_ALTn production n.
;  An X suffix names a directory (GR_ROWX, GR_ALTX, GR_ALTXH, GR_ACTX), an S
;  the base its offsets count from (GR_ROWS, GR_ALTS; GR_ALTHI for the high
;  half), _N a count, and _E or XE an end. The directories hold numbers, not
;  label differences, because ATOM takes a forward reference only as one
;  symbol with a small addend; each entry's comment gives the difference it
;  stands for and the nonterminal. The row and body labels are kept for
;  those comments and for listings; nothing references them.
;
;  Comments on GR_ACTX name the grammar's action: a: is a semantic action,
;  x: an island where a hand-written parser (expressions, initializers,
;  steps, name statements) takes over. A routine that serves several
;  actions derives what differs from the ordinal (the equates below).

GR_ROW_N EQU  50               ; Nonterminals, one row each.
GR_ALT_N EQU  86               ; Productions.
GR_SPLIT EQU  67               ; First production in the high directory.
GR_ACT_N EQU  99               ; Actions in GR_ACTX.
GR_START EQU  $40              ; Start symbol: compilation-unit, row 0.
GR_RHIGH EQU  45               ; First row whose offset counts from GR_ROWS+256.
GR_STMT EQU  $40+28            ; The statement nonterminal, row 28.
GR_EXIT EQU  53                ; Action ordinal of EmitExit (AC_GOTO).
GR_CONT EQU  54                ; Action ordinal of EmitContinue (AC_GOTO).
GR_TO EQU  68                  ; Action ordinal of ForTo (AC_FORTO).
GR_UNTIL EQU  69               ; Action ordinal of ForUntil (AC_FORTO).

; Row directory: offset from GR_ROWS, diagnostic when nothing is predicted.

GR_ROWX:
    DB   0,DG_DECL                 ; GR_ROW0-GR_ROWS; compilation-unit
    DB   11,DG_DECL                ; GR_ROW1-GR_ROWS; top-level-list
    DB   23,DG_DECL                ; GR_ROW2-GR_ROWS; top-level-declaration
    DB   35,DG_DECL                ; GR_ROW3-GR_ROWS; private-declaration
    DB   49,DG_DECL                ; GR_ROW4-GR_ROWS; const-declaration
    DB   51,DG_EQ                  ; GR_ROW5-GR_ROWS; const-declaration-tail
    DB   55,DG_DECL                ; GR_ROW6-GR_ROWS; assert-declaration
    DB   57,DG_DECL                ; GR_ROW7-GR_ROWS; program-var-declaration
    DB   59,DG_EQ                  ; GR_ROW8-GR_ROWS; program-initializer-opt
    DB   63,DG_DECL                ; GR_ROW9-GR_ROWS; record-declaration
    DB   65,DG_EMPTY               ; GR_ROW10-GR_ROWS; record-fields
    DB   67,DG_NAME                ; GR_ROW11-GR_ROWS; record-field-tail
    DB   71,DG_NAME                ; GR_ROW12-GR_ROWS; record-field
    DB   73,DG_FORW                ; GR_ROW13-GR_ROWS; forward-declaration
    DB   75,DG_SUB                 ; GR_ROW14-GR_ROWS; forward-tail
    DB   79,DG_DECL                ; GR_ROW15-GR_ROWS; pool-declaration
    DB   81,DG_SUB                 ; GR_ROW16-GR_ROWS; sub-definition
    DB   83,DG_LPAR                ; GR_ROW17-GR_ROWS; sub-definition-tail
    DB   87,DG_RPAR                ; GR_ROW18-GR_ROWS; parameter-list
    DB   92,DG_RPAR                ; GR_ROW19-GR_ROWS; parameter-tail
    DB   96,DG_NAME                ; GR_ROW20-GR_ROWS; parameter
    DB   100,DG_EOL                ; GR_ROW21-GR_ROWS; result-opt
    DB   105,DG_TYPE               ; GR_ROW22-GR_ROWS; result-var-opt
    DB   111,DG_EOL                ; GR_ROW23-GR_ROWS; fails-opt
    DB   115,DG_STMT               ; GR_ROW24-GR_ROWS; routine-body
    DB   133,DG_VAR                ; GR_ROW25-GR_ROWS; local-declaration
    DB   135,DG_EOL                ; GR_ROW26-GR_ROWS; local-initializer-opt
    DB   139,DG_STMT               ; GR_ROW27-GR_ROWS; statement-sequence
    DB   158,DG_STMT               ; GR_ROW28-GR_ROWS; statement
    DB   182,DG_CASE               ; GR_ROW29-GR_ROWS; select-arms
    DB   186,DG_VALUE              ; GR_ROW30-GR_ROWS; case-arm
    DB   200,DG_RET                ; GR_ROW31-GR_ROWS; return-statement
    DB   202,DG_EOL                ; GR_ROW32-GR_ROWS; return-value-opt
    DB   215,DG_KFAIL              ; GR_ROW33-GR_ROWS; fail-statement
    DB   217,DG_EOL                ; GR_ROW34-GR_ROWS; name-statement-tail
    DB   221,DG_LOOP               ; GR_ROW35-GR_ROWS; transfer-statement
    DB   225,DG_IF                 ; GR_ROW36-GR_ROWS; if-statement
    DB   227,DG_STMT               ; GR_ROW37-GR_ROWS; if-tail
    DB   233,DG_VALUE              ; GR_ROW38-GR_ROWS; while-statement
    DB   235,DG_FOR                ; GR_ROW39-GR_ROWS; for-statement
    DB   237,DG_UPTO               ; GR_ROW40-GR_ROWS; for-bound
    DB   241,DG_EOL                ; GR_ROW41-GR_ROWS; for-step-opt
    DB   245,DG_TYPE               ; GR_ROW42-GR_ROWS; type
    DB   249,DG_TYPE               ; GR_ROW43-GR_ROWS; type-atom
    DB   255,DG_TYPE               ; GR_ROW44-GR_ROWS; type-optional-opt
    DB   9,DG_VALUE                ; GR_ROW45-GR_ROWS-256; string-capacity
    DB   22,DG_VALUE               ; GR_ROW46-GR_ROWS-256; type-array-opt
    DB   31,DG_VALUE               ; GR_ROW47-GR_ROWS-256; array-bound
    DB   44,DG_TYPE                ; GR_ROW48-GR_ROWS-256; scalar-type
    DB   46,DG_TYPE                ; GR_ROW49-GR_ROWS-256; local-shape
GR_ROWXE:                      ; End of the row directory.

